/** Chạy `fn` RUNS lượt, trả ms TRUNG BÌNH + mảng rows của lượt cuối. */
async function measure(fn) {
  let total = 0;
  let rows;
  for (let i = 0; i < RUNS; i++) {
    const t0 = performance.now();
    rows = await fn();
    total += performance.now() - t0;
  }
  return { ms: total / RUNS, rows };
}

